Modify the `CanvasRenderer` component to handle resizing and scaling.

```jsx
import React, { useEffect, useRef } from 'react';

const CanvasRenderer = ({ agents }) => {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');

    const resizeCanvas = () => {
      const container = canvas.parentElement;
      const width = container.clientWidth;
      const height = container.clientHeight;

      canvas.width = width;
      canvas.height = height;

      // Scale the context to maintain pixel density
      const pixelRatio = window.devicePixelRatio || 1;
      const backingStoreRatio =
        ctx.webkitBackingStorePixelRatio ||
        ctx.mozBackingStorePixelRatio ||
        ctx.msBackingStorePixelRatio ||
        ctx.oBackingStorePixelRatio ||
        ctx.backingStorePixelRatio || 1;

      const ratio = pixelRatio / backingStoreRatio;

      canvas.style.width = `${width}px`;
      canvas.style.height = `${height}px`;
      canvas.width = width * ratio;
      canvas.height = height * ratio;
      ctx.scale(ratio, ratio);

      drawCircles(ctx, agents);
    };

    const drawCircles = (ctx, agents) => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      agents.forEach((agent, index) => {
        const x = (index % 5) * 50 + 25; // Position along x-axis
        const y = Math.floor(index / 5) * 50 + 25; // Position along y-axis
        ctx.beginPath();
        ctx.arc(x, y, 20, 0, Math.PI * 2);
        ctx.fillStyle = 'blue';
        ctx.fill();
        ctx.closePath();
      });
    };

    resizeCanvas();

    window.addEventListener('resize', resizeCanvas);

    return () => {
      window.removeEventListener('resize', resizeCanvas);
    };
  }, [agents]);

  return (
    <div className="canvas-container">
      <canvas ref={canvasRef}></canvas>
    </div>
  );
};

export default CanvasRenderer;
```

