```python
import logging

class IncidentResponse:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.ERROR)
        handler = logging.FileHandler('incident_response.log')
        formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
        handler.setFormatter(formatter)
        self.logger.addHandler(handler)

    def handle_incident(self, incident_data):
        try:
            # Log incident and respond with acknowledgement
            self.logger.error(f"Received incident: {incident_data}")
            return {'message': 'Incident acknowledged'}
        except Exception as e:
            self.logger.error(f"Error handling incident: {e}")
            return {'message': 'Error handling incident', 'error': str(e)}
