### Example Implementation with Thread Pool

```java
import java.util.concurrent.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.Iterator;
import java.util.Map;

public class EventSync {
    private final ConcurrentHashMap<String, Event> events = new ConcurrentHashMap<>();
    private final int batchSize = 100; // Adjust batch size as needed
    private final ExecutorService executorService;

    public EventSync(int poolSize) {
        this.executorService = Executors.newFixedThreadPool(poolSize);
    }

    public void syncEvents() {
        Iterator<Map.Entry<String, Event>> iterator = events.entrySet().iterator();
        int count = 0;
        while (iterator.hasNext()) {
            Map.Entry<String, Event> entry = iterator.next();
            submitEventProcessing(entry.getValue());
            count++;
            if (count >= batchSize) {
                break;
            }
        }
    }

    private void submitEventProcessing(Event event) {
        executorService.submit(() -> processEvent(event));
    }

    private void processEvent(Event event) {
        // Logic to process the event
        // For now, just printing the event
        System.out.println("Processing event: " + event);
    }

    public void addEvent(String eventId, Event event) {
        events.put(eventId, event);
    }

    public void removeEvent(String eventId) {
        events.remove(eventId);
    }

    public void shutdown() {
        executorService.shutdown();
    }

    public static class Event {
        private final String id;
        private final String data;

        public Event(String id, String data) {
            this.id = id;
            this.data = data;
        }

        @Override
        public String toString() {
            return "Event{" +
                    "id='" + id + '\'' +
                    ", data='" + data + '\'' +
                    '}';
        }
    }
}
```

